    function safeFilename(value){return String(value||'chemical-diagram').replace(/[\\/:*?"<>|]+/g,'-').trim()||'chemical-diagram';}
    function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},0);}
    function makeToken(){return`[[qmx-diagram:${Diagram.encodeSpec(state.document)}]]`;}
    function insertIntoQuestion(){const textarea=state.context?.textarea||window.QmxDiagramLauncher?.getActiveTextarea?.();if(!textarea){setStatus('No active question textarea found.');return;}const token=makeToken();if(state.context?.replaceRange){const{start,end}=state.context.replaceRange;textarea.setRangeText(token,start,end,'end');state.context.replaceRange={start,end:start+token.length};}else{const start=textarea.selectionStart??textarea.value.length,end=textarea.selectionEnd??start;textarea.setRangeText(token,start,end,'end');state.context.replaceRange={start,end:start+token.length};}textarea.dispatchEvent(new Event('input',{bubbles:true}));textarea.dispatchEvent(new Event('change',{bubbles:true}));setStatus('Chemical diagram inserted into the question.');close();}
